import * as T from './vendor/three.module.js';

// Original character clothing, never product stock or an owned catalog item.
let templates;
function loft(rings,segments=48,power=1){const positions=[],uv=[],index=[];for(const [row,[y,rx,front,back]]of rings.entries())for(let i=0;i<=segments;i++){const a=i/segments*Math.PI*2;positions.push(Math.sign(Math.cos(a))*Math.abs(Math.cos(a))**power*rx,y,Math.sign(Math.sin(a))*Math.abs(Math.sin(a))**power*(Math.sin(a)>=0?front:back));uv.push(i/segments,row/(rings.length-1));if(row<rings.length-1&&i<segments){const k=row*(segments+1)+i;index.push(k,k+segments+1,k+1,k+1,k+segments+1,k+segments+2);}}const geo=new T.BufferGeometry();geo.setAttribute('position',new T.Float32BufferAttribute(positions,3));geo.setAttribute('uv',new T.Float32BufferAttribute(uv,2));geo.setIndex(index);geo.computeVertexNormals();return geo;}
function merge(parts){const positions=[],normals=[],uv=[],indices=[];for(const g of parts){const offset=positions.length/3;positions.push(...g.attributes.position.array);normals.push(...g.attributes.normal.array);uv.push(...g.attributes.uv.array);indices.push(...Array.from(g.index.array,n=>n+offset));g.dispose();}const out=new T.BufferGeometry();out.setAttribute('position',new T.Float32BufferAttribute(positions,3));out.setAttribute('normal',new T.Float32BufferAttribute(normals,3));out.setAttribute('uv',new T.Float32BufferAttribute(uv,2));out.setIndex(indices);return out;}
function details(){
 const parts=[],tube=(points,r=.045)=>parts.push(new T.TubeGeometry(new T.CatmullRomCurve3(points.map(p=>new T.Vector3(...p))),24,r,5,false)),rings=[[23.3,5.3,4.1,3.9],[25,5.5,4.4,3.82],[26.7,5.45,4.35,3.25],[27.7,5.4,4.38,3.1],[28.15,5.4,4.38,3.1]],at=(x,y,back=false)=>{let a=rings[0],b=rings.at(-1);for(let i=1;i<rings.length;i++)if(y<=rings[i][0]){a=rings[i-1];b=rings[i];break;}const t=Math.max(0,Math.min(1,(y-a[0])/(b[0]-a[0]))),rx=a[1]+(b[1]-a[1])*t,depth=a[back?3:2]+(b[back?3:2]-a[back?3:2])*t,z=depth*Math.max(0,1-(Math.abs(x)/rx)**(2/.65))**(.65/2)+.065;return [x,y,(back?-1:1)*z];};
 for(const y of [27.7,28.05])tube(Array.from({length:49},(_,i)=>{const a=i/48*Math.PI*2;return [Math.sign(Math.cos(a))*Math.abs(Math.cos(a))**.65*5.46,y,Math.sign(Math.sin(a))*Math.abs(Math.sin(a))**.65*(Math.sin(a)>0?4.45:3.17)];}));
 tube([[0,28],[.12,27],[.18,26.1],[.2,25.2]].map(([x,y])=>at(x,y)),.055);
 for(const sign of [-1,1]){tube([[sign*2.1,27.6],[sign*2.9,27],[sign*3.8,26.1],[sign*4.5,25.2]].map(([x,y])=>at(x,y)));tube([[sign*1.4,27.3],[sign*1.5,26.1],[sign*2.5,25.6],[sign*3.7,26.1],[sign*3.7,27.3]].map(([x,y])=>at(x,y,true)));}
 const button=new T.SphereGeometry(.13,8,6);button.scale(1,1,.35);button.translate(...at(0,27.88));parts.push(button);return merge(parts);
}
export function addStarterTrousers(w,g,material){
 const anatomy=g.userData.anatomy;if(!anatomy)return;
 if(!templates){templates=new Map();for(const name of ['pelvis','thigh_r','thigh_l','calf_r','calf_l']){const geo=anatomy.meshes.get(name).geometry.clone(),p=geo.attributes.position,n=geo.attributes.normal;for(let i=0;i<p.count;i++){p.setXYZ(i,p.getX(i)+n.getX(i)*.045,p.getY(i)+n.getY(i)*.045,p.getZ(i)+n.getZ(i)*.045);}geo.computeVertexNormals();templates.set(name,geo);}templates.set('waist',loft([[23.3,5.3,4.1,3.9],[25,5.5,4.4,3.82],[26.7,5.45,4.35,3.25],[27.7,5.4,4.38,3.1],[28.15,5.4,4.38,3.1]],48,.65));templates.set('cuff',loft([[-10.68,1.46,1.05,1.45],[-10.5,1.48,1.07,1.47],[-9.8,1.44,1.05,1.43]],32));templates.set('details',details());}
 w.starterTrouserGeometries??=new Map([...templates].map(([k,v])=>[k,v.clone()]));w.humanSharedResources??=new Set();
 for(const geo of w.starterTrouserGeometries.values()){w.resources.add(geo);w.humanSharedResources.add(geo);}
 const group=new T.Group();group.name='starter-trousers';group.userData.role='original-starter-trousers';g.add(group);
 for(const name of ['pelvis','thigh_r','thigh_l','calf_r','calf_l']){const original=anatomy.meshes.get(name),mesh=new T.SkinnedMesh(w.starterTrouserGeometries.get(name),material);mesh.name='starter-trousers:'+name;mesh.castShadow=mesh.receiveShadow=true;mesh.frustumCulled=false;group.add(mesh);mesh.bind(anatomy.skeleton,original.bindMatrix);original.visible=false;}
 const waist=w.mesh(w.starterTrouserGeometries.get('waist'),material,group);waist.name='starter-waistband';g.userData.starterTrouserExtras=[];for(const leg of g.userData.limbs.slice(2)){const cuff=w.mesh(w.starterTrouserGeometries.get('cuff'),material,leg.userData.knee);cuff.name='starter-trouser-cuff';g.userData.starterTrouserExtras.push(cuff);}
 const trim=w.mat(material.color.clone().multiplyScalar(.68),{roughness:.95,envMapIntensity:.25});const seams=w.mesh(w.starterTrouserGeometries.get('details'),trim,group);seams.name='starter-trouser-stitching';g.userData.starterTrousers=group;
}
export function hideStarterTrousers(g){if(g.userData.starterTrousers)g.userData.starterTrousers.visible=false;for(const cuff of g.userData.starterTrouserExtras||[])cuff.visible=false;}
